			hint = "Ayude a Oralius a quebrar el ánimo de los ogros Firegut.",
			text = [=[Cuando cayó {link:gor-tesh}Gor'tesh{/link}, Oralius clavó la cabeza del señor {link:ogres}ogro{/link} en una pica e hizo que la llevaran a lo alto de la {link:dreadmaul-rock}Roca Machacamiedo{/link}, seguro de que la visión haría huir aterrados a los ogros. Después preguntó si alguien había pintado un cuadro de la escena.]=],
