		{ text = "Lo bueno" },
	},
	bonds = {
		{ id = "gor-tesh", name = "Gor'tesh", note = "el señor ogro que marcó para la muerte" },
		{ id = "marshal-maxwell", name = "Mariscal Maxwell", note = "su comandante" },
