Translate("esMX", "tinkee-steamboil", {
	title = "Tinkee Steamboil",
	subtitle = "Estudiosa de los dragonantes",
	found = "Peñasco Llamarada",
	hint = [=[Hable con la inventora del Peñasco Llamarada que estudia a los dragonantes de las Estepas.]=],
	allegiance = "Un patrón oculto",
	sections = {
		{
			title = "Resumen",
			text = [=[Tinkee Steamboil es una inventora que ha pasado semanas estudiando a los dragonantes de {link:burning-steppes}las Estepas{/link} desde el {link:flame-crest}Peñasco Llamarada{/link}. Sus aparatos capturan la esencia de las crías y congelan los huevos de los dragones negros. Sueña con ser la envidia de los estudiosos de dragones de todo el mundo. También sirve a un patrón al que no quiere nombrar, y advierte que no es alguien a quien convenga decepcionar.]=],
		},
		{
			title = "Importancia",
			text = [=[El trabajo de Tinkee debía entregar los huevos del Vuelo Negro a manos peligrosas. Que no lo hiciera no fue mérito suyo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Construyó el Draco-Incarcinatrix 900 para extraer la esencia de las crías.
• Buscó piezas de {link:felnok-steelspring}Felnok Steelspring{/link} en {link:everlook}Vista Eterna{/link} para congelar huevos de dragón.
• Envió buscadores a la nidada de la Cumbre de {link:blackrock-mountain}Roca Negra{/link} en busca de huevos.]=],
		},
	},
	chapters = {
		{
			title = "Los huevos del amo",
			hint = "Lleve los huevos congelados adonde ordene el amo de Tinkee.",
			text = [=[Llegó un mensaje, al parecer de su amo, Vectus. Lo firmaba un hombre del que ella nunca había oído hablar: {link:leonid-barthalomew}Leonid Barthalomew{/link}, en la {link:light-s-hope-chapel}Capilla de la Esperanza de la Luz{/link}. A Tinkee le dolió que su amo confiara los huevos a otro, pero los envió. Leonid no era siervo de Vectus. Era un caballero del {link:argent-dawn}Alba Argenta{/link}, y la había engañado para que los huevos nunca llegaran al poder al que ella había servido.]=],
		},
	},
	mentions = {
		{ text = "Esencia de cría" },
		{ text = "{link:felnok-steelspring}Felnok Steelspring{/link}" },
